import{_ as t,o as i,c as n,ae as a}from"./chunks/framework.BX6FPmO9.js";const u=JSON.parse('{"title":"Remix ESLint 棄用說明","description":"","frontmatter":{},"headers":[],"relativePath":"conventions/eslint-remix-deprecation.md","filePath":"conventions/eslint-remix-deprecation.md"}'),r={name:"conventions/eslint-remix-deprecation.md"};function o(s,e,l,c,d,m){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="remix-eslint-棄用說明" tabindex="-1">Remix ESLint 棄用說明 <a class="header-anchor" href="#remix-eslint-棄用說明" aria-label="Permalink to &quot;Remix ESLint 棄用說明&quot;">​</a></h1><p><strong>類型</strong>：reference | <strong>權重</strong>：3</p><h2 id="警告訊息是什麼" tabindex="-1">警告訊息是什麼？ <a class="header-anchor" href="#警告訊息是什麼" aria-label="Permalink to &quot;警告訊息是什麼？&quot;">​</a></h2><p>執行 <code>pnpm run lint</code> 時若看到：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REMIX FUTURE CHANGE: The `@remix-run/eslint-config` package is deprecated</span></span>\n<span class="line"><span>and will not be included in React Router v7. We recommend moving towards</span></span>\n<span class="line"><span>a streamlined ESLint config such as the ones included in the Remix templates.</span></span></code></pre></div><p>代表目前專案使用的 <strong><code>@remix-run/eslint-config</code></strong> 已被 Remix 標記為棄用，且 <strong>React Router v7 將不再內含此套件</strong>。</p><h2 id="為什麼棄用" tabindex="-1">為什麼棄用？ <a class="header-anchor" href="#為什麼棄用" aria-label="Permalink to &quot;為什麼棄用？&quot;">​</a></h2><ul><li>Remix 團隊認為 ESLint 設定屬於「各專案自己的選擇」，不適合由 Remix 核心提供一套固定配置。</li><li>建議改由各專案自行組合 <strong>eslint 官方與各 plugin 的 recommended</strong>（例如 TypeScript、React、jsx-a11y），不再依賴 Remix 的集中式 config。</li></ul><h2 id="現在需要做什麼" tabindex="-1">現在需要做什麼？ <a class="header-anchor" href="#現在需要做什麼" aria-label="Permalink to &quot;現在需要做什麼？&quot;">​</a></h2><ul><li><strong>短期</strong>：<strong>不用立刻改</strong>。現有 <code>.eslintrc.cjs</code> 仍可正常使用，lint 照常跑；只是會看到上述警告。</li><li><strong>中長期</strong>：升級到 React Router v7 前，規劃把 ESLint 改為「精簡版」： <ul><li>移除 <code>extends: [&quot;@remix-run/eslint-config&quot;, &quot;@remix-run/eslint-config/node&quot;]</code>。</li><li>改為直接 extend：<code>eslint:recommended</code>、<code>plugin:@typescript-eslint/recommended</code>、<code>plugin:react/recommended</code>、<code>plugin:react-hooks/recommended</code>、<code>plugin:jsx-a11y/recommended</code> 等（可參考 <a href="https://github.com/remix-run/remix/blob/main/templates/remix/.eslintrc.cjs" target="_blank" rel="noreferrer">Remix 官方 template 的 .eslintrc.cjs</a>）。</li><li>現有自訂規則（simple-import-sort、tailwind、promise、security 等）可保留，只替換「Remix 那兩行」的來源。</li></ul></li></ul><h2 id="參考" tabindex="-1">參考 <a class="header-anchor" href="#參考" aria-label="Permalink to &quot;參考&quot;">​</a></h2><ul><li>Remix 說明：<a href="https://github.com/remix-run/remix/blob/v2/templates/remix/.eslintrc.cjs" target="_blank" rel="noreferrer">https://github.com/remix-run/remix/blob/v2/templates/remix/.eslintrc.cjs</a></li><li>若日後要遷移，可依 <a href="./../code-review-spec.html">Code Review 規範</a> 在變更後更新本文件與 <code>package.json</code> 依賴。</li></ul>',12)])])}const h=t(r,[["render",o]]);export{u as __pageData,h as default};
